"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Compile-time tiling parameters
constexpr int TILE_OH    = 8;
constexpr int TILE_OW    = 8;   // number of threads along the ow dimension
constexpr int OW_REG     = 4;    // register-blocked outputs per thread along width
constexpr int Threads    = TILE_OH * TILE_OW; // 64
constexpr int CoPerBlock = 8;
template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride, int padding,
    int Hout, int Wout,
    int IHTile, int IWTile, int WTiles)
{
  const int tid = threadIdx.x;
  const int n        = blockIdx.z;
  const int p_tile_idx = blockIdx.x;
  const int h_tile_idx = p_tile_idx / WTiles;
  const int w_tile_idx = p_tile_idx % WTiles;
  const int oh_base = h_tile_idx * TILE_OH;
  const int ow_tile_width = TILE_OW * OW_REG;
  const int ow_base = w_tile_idx * ow_tile_width;
  const int local_oh = tid / TILE_OW;
  const int local_ow_grp = tid % TILE_OW;
  const int oh = oh_base + local_oh;
  const int ow0 = ow_base + local_ow_grp;
  const bool valid_row = (oh < Hout);
  // Strides for global tensors (row-major, contiguous)
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sWco = (int64_t)Cin * Kh * Kw;
  const int64_t sWci = (int64_t)Kh * Kw;
  const int64_t sWkh = (int64_t)Kw;
  // Global CuTe tensors
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, Kh, Kw),
      make_stride(sWco, sWci, sWkh, Int<1>{})
  );
  // Shared memory: [weight cache][input patch cache]
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  const int64_t s_sci = (int64_t)Kh * Kw;
  const int64_t s_sco = (int64_t)Cin * Kh * Kw;
  const int64_t s_skh = (int64_t)Kw;
  const int64_t s_buf = (int64_t)CoPerBlock * (int64_t)Cin * (int64_t)Kh * (int64_t)Kw;
  // Double-buffered weight tile cache to allow pipelined prefetch of the
  // next output-channel tile's weights while computing with the current one.
  auto sW2 = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<2>{}, Int<CoPerBlock>{}, Cin, Kh, Kw),
      make_stride(s_buf, s_sco, s_sci, s_skh, Int<1>{})
  );
  T* sX_ptr = sW_ptr + (size_t)2 * (size_t)CoPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw;
  const int64_t sXci = (int64_t)IHTile * IWTile;
  const int64_t sXhi = (int64_t)IWTile;
  auto sXp = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Cin, IHTile, IWTile),
      make_stride(sXci, sXhi, Int<1>{})
  );
  // Load input patch (receptive field of the whole output tile) into shared
  // memory ONCE, and reuse it across all output-channel tiles handled by this
  // block (avoids redundant global-memory reloads of the input tile).
  const int ih_patch_base = oh_base * stride - padding;
  const int iw_patch_base = ow_base * stride - padding;
  const int total_x = Cin * IHTile * IWTile;
  for (int idx = tid; idx < total_x; idx += Threads) {
    int rem = idx;
    int iw_l = rem % IWTile; rem /= IWTile;
    int ih_l = rem % IHTile; rem /= IHTile;
    int ci_i = rem;
    int ih_g = ih_patch_base + ih_l;
    int iw_g = iw_patch_base + iw_l;
    T xval = T(0);
    if ((unsigned)ih_g < (unsigned)H && (unsigned)iw_g < (unsigned)Win) {
      xval = mX(ci_i, ih_g, iw_g);
    }
    sXp(ci_i, ih_l, iw_l) = xval;
  }
  __syncthreads();
  const int num_co_tiles = (Cout + CoPerBlock - 1) / CoPerBlock;
  const int total_w = CoPerBlock * Cin * Kh * Kw;
  // Prefetch weights for the first output-channel tile into buffer 0.
  for (int idx = tid; idx < total_w; idx += Threads) {
    int rem = idx;
    int kw_i = rem % Kw; rem /= Kw;
    int kh_i = rem % Kh; rem /= Kh;
    int ci_i = rem % Cin; rem /= Cin;
    int co_i = rem;
    int co_g = co_i;
    T wval = T(0);
    if (co_g < Cout) {
      wval = mW(co_g, ci_i, kh_i, kw_i);
    }
    sW2(0, co_i, ci_i, kh_i, kw_i) = wval;
  }
  __syncthreads();
  for (int co_tile = 0; co_tile < num_co_tiles; ++co_tile) {
    const int co_base = co_tile * CoPerBlock;
    const int cur_buf = co_tile & 1;
    const int next_buf = cur_buf ^ 1;
    // Pipelined prefetch: load the next output-channel tile's weights into
    // the other buffer while computing with the current buffer below,
    // hiding global-memory latency behind arithmetic work.
    if (co_tile + 1 < num_co_tiles) {
      const int next_co_base = (co_tile + 1) * CoPerBlock;
      for (int idx = tid; idx < total_w; idx += Threads) {
        int rem = idx;
        int kw_i = rem % Kw; rem /= Kw;
        int kh_i = rem % Kh; rem /= Kh;
        int ci_i = rem % Cin; rem /= Cin;
        int co_i = rem;
        int co_g = next_co_base + co_i;
        T wval = T(0);
        if (co_g < Cout) {
          wval = mW(co_g, ci_i, kh_i, kw_i);
        }
        sW2(next_buf, co_i, ci_i, kh_i, kw_i) = wval;
      }
    }
    // Accumulators, init with bias. Register-blocked over OW_REG output columns.
    float acc[CoPerBlock][OW_REG];
    #pragma unroll
    for (int cc = 0; cc < CoPerBlock; ++cc) {
      int co_g = co_base + cc;
      float bval = 0.0f;
      if (B != nullptr && co_g < Cout) {
        bval = (float)B[co_g];
      }
      #pragma unroll
      for (int r = 0; r < OW_REG; ++r) {
        acc[cc][r] = bval;
      }
    }
    // Main compute loop: reuse cached input patch and weights from shared memory
    // across OW_REG output columns per thread (register blocking).
    if (valid_row) {
      for (int kh = 0; kh < Kh; ++kh) {
        int ih_l = local_oh * stride + kh;
        for (int kw = 0; kw < Kw; ++kw) {
          for (int ci = 0; ci < Cin; ++ci) {
            float xval[OW_REG];
            #pragma unroll
            for (int r = 0; r < OW_REG; ++r) {
              int iw_l = (local_ow_grp + r * TILE_OW) * stride + kw;
              xval[r] = (float)sXp(ci, ih_l, iw_l);
            }
            #pragma unroll
            for (int cc = 0; cc < CoPerBlock; ++cc) {
              float wval = (float)sW2(cur_buf, cc, ci, kh, kw);
              #pragma unroll
              for (int r = 0; r < OW_REG; ++r) {
                acc[cc][r] += xval[r] * wval;
              }
            }
          }
        }
      }
    }
    // Store results
    #pragma unroll
    for (int r = 0; r < OW_REG; ++r) {
      int ow_r = ow0 + r * TILE_OW;
      if (!(oh < Hout) || !(ow_r < Wout)) continue;
      #pragma unroll
      for (int cc = 0; cc < CoPerBlock; ++cc) {
        int co_g = co_base + cc;
        if (co_g >= Cout) continue;
        mY(co_g, oh, ow_r) = static_cast<T>(acc[cc][r]);
      }
    }
    // Single barrier per tile: makes the prefetch into next_buf visible for
    // the following iteration and ensures all reads of cur_buf have
    // completed before it is overwritten two iterations later.
    __syncthreads();
  }
}
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - Kh) / stride + 1;
  int64_t Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  int h_tiles = (int)((Hout + TILE_OH - 1) / TILE_OH);
  int ow_tile_width = TILE_OW * OW_REG;
  int w_tiles = (int)((Wout + ow_tile_width - 1) / ow_tile_width);
  int IH_TILE = (TILE_OH - 1) * stride + (int)Kh;
  int IW_TILE = (ow_tile_width - 1) * stride + (int)Kw;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(h_tiles * w_tiles),
      1u,
      (unsigned)N
  );
  size_t smem_bytes = (size_t)2 * (size_t)CoPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float)
                     + (size_t)Cin * (size_t)IH_TILE * (size_t)IW_TILE * sizeof(float);
  int device_id = 0;
  cudaGetDevice(&device_id);
  int max_optin_smem = 0;
  cudaDeviceGetAttribute(&max_optin_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
  TORCH_CHECK((size_t)max_optin_smem >= smem_bytes,
      "Required shared memory (", smem_bytes,
      " bytes) exceeds device max opt-in shared memory (", max_optin_smem, " bytes).");
  cudaError_t attr_err = cudaFuncSetAttribute(
      conv2d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess,
      "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes,
      ": ", cudaGetErrorString(attr_err));
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout,
      IH_TILE, IW_TILE, w_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
